package imgix_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/xantiagoma/xtandard-image/internal/dialect"
	"github.com/xantiagoma/xtandard-image/internal/security/sign"
	"github.com/xantiagoma/xtandard-image/internal/transform"
)

// jsCoreEntry is one URL generated by @imgix/js-core
// (testdata/jscore/generate.ts).
type jsCoreEntry struct {
	Name   string         `json:"name"`
	Params map[string]any `json:"params"`
	Path   string         `json:"path"`
	Query  string         `json:"query"`
	Source string         `json:"source"`
}

func loadJSCore(tb testing.TB) []jsCoreEntry {
	tb.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", "jscore", "corpus.json"))
	if err != nil {
		tb.Fatal(err)
	}
	var corpus []jsCoreEntry
	if err := json.Unmarshal(b, &corpus); err != nil {
		tb.Fatal(err)
	}
	return corpus
}

// TestJSCoreCorpus parses URLs built and signed by the official imgix URL
// builder; the expected requests are in golden/jscore.json. Every URL must
// verify with the blueprint token and round-trip its source.
func TestJSCoreCorpus(t *testing.T) {
	t.Parallel()
	corpus := loadJSCore(t)
	if len(corpus) < 40 {
		t.Fatalf("corpus has %d entries, want >= 40", len(corpus))
	}
	cases := make([]testCase, 0, len(corpus))
	for _, e := range corpus {
		cases = append(cases, testCase{name: e.Name, cfg: "required", path: e.Path, query: e.Query})
	}
	runGolden(t, "jscore", cases)

	p := getFixture(t).parsers["required"]
	for _, e := range corpus {
		res, err := p.Parse(&dialect.Input{Path: e.Path, RawQuery: e.Query})
		if err != nil {
			t.Errorf("%s: %v", e.Name, err)
			continue
		}
		if res.Signature != sign.Verified {
			t.Errorf("%s: signature %v", e.Name, res.Signature)
		}
		if res.SourceString != e.Source {
			t.Errorf("%s: source %q, want %q", e.Name, res.SourceString, e.Source)
		}
	}
}

// unpicCase is one assertion of unpic's imgix provider tests
// (.refs/unpic/src/providers/imgix.test.ts): the URL unpic parses or
// generates and the operations its tests expect.
type unpicCase struct {
	name    string
	query   string
	width   int
	height  int
	quality int
	format  transform.Format
	fit     transform.ResizeType
	enlarge bool
}

// TestUnpicFixtures parses the URLs of unpic's imgix tests and checks the
// width, height, quality, format and fit its tests assert. unpic's defaults
// are fit=min and auto=format; fit=min is fill-down (never upscale) and
// auto=format leaves the format to negotiation.
func TestUnpicFixtures(t *testing.T) {
	t.Parallel()
	const path = "/photo-1674255909399-9bcb2cab6489"
	cases := []unpicCase{
		// extract: "should parse a URL" / "... with operations".
		{name: "extract_plain", query: ""},
		{name: "extract_operations", query: "w=200&h=300&q=80&fit=crop", width: 200, height: 300, quality: 80, fit: transform.ResizeFill, enlarge: true},
		// generate.
		{name: "generate_wh", query: "w=200&h=100&fit=min&auto=format", width: 200, height: 100, fit: transform.ResizeFillDown},
		{name: "generate_w", query: "w=200&fit=min&auto=format", width: 200, fit: transform.ResizeFillDown},
		{name: "generate_rounded", query: "w=201&h=100&fit=min&auto=format", width: 201, height: 100, fit: transform.ResizeFillDown},
		{name: "generate_format", query: "w=200&fit=min&fm=webp", width: 200, format: transform.FormatWebP, fit: transform.ResizeFillDown},
		// transform.
		{name: "transform_defaults", query: "w=200&h=300&fit=min&auto=format", width: 200, height: 300, fit: transform.ResizeFillDown},
		{name: "transform_no_operations", query: "fit=min&auto=format", fit: transform.ResizeFillDown},
		{name: "transform_format_in_url", query: "w=200&fm=webp&fit=min", width: 200, format: transform.FormatWebP, fit: transform.ResizeFillDown},
		// Non-integer widths as unpic would pass them through unrounded.
		{name: "unrounded_width", query: "w=200.6&h=100.2&fit=min&auto=format", width: 201, height: 100, fit: transform.ResizeFillDown},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			for _, cfg := range []string{"default", "strict"} {
				res, err := getFixture(t).parsers[cfg].Parse(&dialect.Input{Path: path, RawQuery: tc.query})
				if err != nil {
					t.Fatalf("%s: %v", cfg, err)
				}
				r := res.Request
				rs := r.Pipelines[0].Resize
				got := unpicCase{
					name: tc.name, query: tc.query,
					width: rs.Width.Px, height: rs.Height.Px, quality: r.Output.Quality,
					format: r.Output.Format, fit: rs.Type, enlarge: rs.Enlarge,
				}
				if got != tc {
					t.Fatalf("%s: got %+v, want %+v", cfg, got, tc)
				}
				if len(r.Ignored) != 0 {
					t.Fatalf("%s: ignored %v", cfg, r.Ignored)
				}
			}
		})
	}
}
